function uniqueSortedNumbers(values) {
  // Ensure we don't mutate input and work with a shallow copy
  const numbers = Array.isArray(values) ? values.slice() : [];
  // Use a Set to remove duplicates, then sort numerically
  const unique = Array.from(new Set(numbers));
  unique.sort((a, b) => a - b);
  return unique;
}

// Assertions
console.assert(
  JSON.stringify(uniqueSortedNumbers([3, 1, 2, 3, 2])) === JSON.stringify([1, 2, 3]),
  'Duplicates are removed and result is sorted'
);

console.assert(
  JSON.stringify(uniqueSortedNumbers([ -1, -3, -2, -1, 0, 2, 2])) === JSON.stringify([-3, -2, -1, 0, 2]),
  'Negative numbers are handled correctly and duplicates removed'
);

console.assert(
  JSON.stringify(uniqueSortedNumbers([])) === JSON.stringify([]),
  'Empty array returns empty array'
);
